INSERT INTO `diseasepredictions` VALUES (1,0,'Diagnosis-Management-Foliar-Diseases-2.jpg','Bacterial Blight (Angular Leaf Spot)',95,'Cause: Xanthomonas citri subsp. malvacearum bacteria, thriving in warm and humid conditions.. Fertilizer: Avoid excessive nitrogen fertilizers. Maintain balanced NPK levels.','Apply copper-based fungicides. Remove and destroy infected crop debris.','Use acid-delinted, certified disease-free seeds. Rotate crops with non-host crops like maize.','State Department of Agriculture','2026-08-01 14:23:33.861800'),(2,0,'Diagnosis-Management-Foliar-Diseases-2.jpg','Bacterial Blight (Angular Leaf Spot)',95,'Cause: Xanthomonas citri subsp. malvacearum bacteria, thriving in warm and humid conditions.. Fertilizer: Avoid excessive nitrogen fertilizers. Maintain balanced NPK levels.','Apply copper-based fungicides. Remove and destroy infected crop debris.','Use acid-delinted, certified disease-free seeds. Rotate crops with non-host crops like maize.','State Department of Agriculture','2026-08-01 14:33:39.097750'),(3,0,'Diagnosis-Management-Foliar-Diseases-2.jpg','Bacterial Blight (Angular Leaf Spot)',95,'Cause: Xanthomonas citri subsp. malvacearum bacteria, thriving in warm and humid conditions.. Fertilizer: Avoid excessive nitrogen fertilizers. Maintain balanced NPK levels.','Apply copper-based fungicides. Remove and destroy infected crop debris.','Use acid-delinted, certified disease-free seeds. Rotate crops with non-host crops like maize.','State Department of Agriculture','2026-08-01 14:35:21.224058'),(4,4,'Diagnosis-Management-Foliar-Diseases-2.jpg','Cercospora Leaf Spot',95,'Cause: Fungal pathogen Cercospora gossypina, often favored by warm, humid weather and plant stress, particularly potassium deficiency.. Fertilizer: Apply adequate Potassium (e.g., Muriate of Potash / KCl) as potassium deficiency severely increases susceptibility to leaf spot diseases. Ensure balanced NPK application.','Apply broad-spectrum or systemic fungicides containing active ingredients such as azoxystrobin, pyraclostrobin, or copper hydroxide upon early appearance of symptoms.','Practice crop rotation with non-host crops, destroy infected crop residues post-harvest, use resistant cotton varieties, and maintain optimal field drainage and plant spacing to reduce canopy humidity.','State Department of Agriculture','2026-08-01 15:09:19.137074'),(5,4,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungus (Alternaria macrospora / Alternaria alternata). Fertilizer: Apply a balanced NPK fertilizer and ensure adequate Potassium (K) supply, as potassium deficiency predisposes leaves to severe spot infection.','Apply foliar fungicides such as Mancozeb, Copper Oxychloride, or Difenoconazole at the onset of disease symptoms.','Use certified disease-free seeds, practice crop rotation with non-host crops, collect and burn crop debris after harvest, and avoid overhead sprinkler irrigation to minimize leaf wetness duration.','State Department of Agriculture','2026-08-01 15:11:55.429025'),(6,4,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria macrospora or Alternaria alternata, favored by warm, humid conditions, prolonged leaf wetness, and nutrient deficiencies.. Fertilizer: Apply balanced fertilizers with sufficient Potassium (e.g., Muriate of Potash) and Nitrogen, as potassium deficiency severely predisposes cotton to Alternaria leaf spot.','Apply foliar fungicides such as Mancozeb, Copper Oxychloride, or Difenoconazole at the first sign of symptoms according to local agricultural guidelines.','Use certified disease-free seeds, practice crop rotation with non-host plants, ensure adequate plant spacing for proper canopy airflow, and manage crop residues post-harvest.','State Department of Agriculture','2026-08-01 15:12:12.709821'),(7,4,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria macrospora or Alternaria alternata, favored by high humidity, warm temperatures, and nutrient stress (especially potassium deficiency).. Fertilizer: Apply balanced soil nutrients with an adequate supply of Potassium (e.g., Muriate of Potash) to reduce crop susceptibility.','Foliar spray of fungicides containing Mancozeb, Copper Oxychloride, Azoxystrobin, or Difenoconazole according to recommended dosages.','Use resistant or certified disease-free seeds, practice crop rotation with non-host crops, maintain proper plant spacing for canopy aeration, and destroy infected crop debris after harvest.','State Department of Agriculture','2026-08-01 15:19:52.047540'),(8,4,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungus (Alternaria macrospora / Alternaria alternata). Fertilizer: Ensure adequate Potassium (K) fertilization, as potassium deficiency significantly increases susceptibility to Alternaria infection. Maintain balanced NPK nutrition.','Foliar application of copper-based fungicides or systemic fungicides like Mancozeb, Difenoconazole, or Azoxystrobin.','Use certified disease-free seeds, destroy infected crop residue after harvest, practice 2-3 year crop rotation, and maintain optimum plant spacing to reduce canopy humidity.','State Department of Agriculture','2026-08-01 15:36:46.513312'),(9,2,'Diagnosis-Management-Foliar-Diseases-2.jpg','Cercospora Leaf Spot',95,'Cause: Fungal infection caused by Cercospora gossypina, often triggered by warm humid conditions and potassium deficiency in plants.. Fertilizer: Apply potassium-rich fertilizers (e.g., Muriate of Potash / K2O) along with balanced NPK nutrients, as potassium deficiency renders leaves highly susceptible to Cercospora infection.','Apply foliar fungicides containing active ingredients such as azoxystrobin, pyraclostrobin, difenoconazole, or copper oxychloride at early onset of symptoms.','Practice crop rotation with non-host crops, clear crop residues post-harvest, maintain optimal plant spacing for adequate air circulation, and use disease-resistant cotton varieties.','State Department of Agriculture','2026-08-02 14:04:21.645345'),(10,2,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungus (Alternaria macrospora / Alternaria alternata). Fertilizer: Ensure adequate Potassium (K) application to reduce plant susceptibility, along with balanced NPK management.','Foliar application of fungicides containing Mancozeb, Copper Oxychloride, Difenoconazole, or Azoxystrobin.','Practice crop rotation with non-host crops, destroy post-harvest crop residue, avoid overhead irrigation, and use certified disease-free seeds.','State Department of Agriculture','2026-08-02 14:05:04.172689'),(11,2,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria macrospora or Alternaria alternata, often triggered by humid weather, rain, and nutrient stress.. Fertilizer: Apply balanced NPK fertilizers with adequate Potassium (Muriate of Potash) to build foliage resistance, as potassium deficiency severely enhances susceptibility.','Foliar application of fungicides such as Copper Oxychloride, Mancozeb, Difenoconazole, or Azoxystrobin upon early detection.','Use disease-free certified seeds, maintain optimal plant spacing for proper canopy airflow, practice crop rotation with non-host crops, and destroy crop residues after harvest.','State Department of Agriculture','2026-08-03 09:57:38.985243'),(12,7,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria macrospora or Alternaria alternata, favored by warm, humid conditions and nutrient stress.. Fertilizer: Apply adequate Potassium (K) fertilizers, such as Muriate of Potash (MOP), as potassium deficiency increases plant susceptibility to Alternaria spot.','Foliar application of fungicides containing Mancozeb, Copper Oxychloride, or Difenoconazole at the early onset of symptoms.','Practice crop rotation with non-host crops, destroy infected crop residues after harvest, maintain proper field spacing for good airflow, and use certified disease-free seeds.','State Department of Agriculture','2026-08-03 12:11:48.268527'),(13,7,'/uploads/diseases/25d92f42-d242-4079-b7f2-3aa572bb485e.jpg','Alternaria Leaf Spot',92,'Circular to irregular brown spots with concentric rings (target-like appearance) and dark purple margins on leaves. The centers of the lesions may become brittle and crack, leading to a shot-hole appearance.','Apply organic copper fungicides or neem oil. Remove and destroy infected crop residues after harvest to reduce fungal inoculum in the soil.','Rotate crops with non-susceptible plants, ensure proper plant spacing for air circulation, avoid overhead irrigation to minimize leaf wetness, and maintain robust plant health through optimal nutrition.','State Department of Agriculture','2026-08-04 10:50:26.695341'),(14,7,'/uploads/diseases/fdcd8250-3ff6-4e29-8adb-c9ccc4a41074.jpg','Alternaria Leaf Spot',92,'Circular to irregular tan or pale brown spots with dark purple or reddish-brown borders on leaves, which may dry up and drop out, creating a shot-hole appearance.','Spray neem oil or copper hydroxide-based organic fungicides, and remove severely affected leaves to prevent spore dispersal.','Maintain adequate potassium nutrition, ensure proper crop spacing for air circulation, avoid overhead irrigation, and apply chemical fungicides such as Mancozeb or Difenoconazole when early symptoms appear.','State Department of Agriculture','2026-08-04 12:37:06.721819'),(15,7,'/uploads/diseases/b5dbae9f-02b3-4f12-80c9-c25fe624aced.jpg','Purple Blotch',94,'Elongated, oval-shaped, sunken lesions with purplish-brown centers and yellowish outer halos on leaves and stalks.','Spray neem oil or Trichoderma harzianum; apply copper oxychloride bio-fungicide formulations to limit fungal spread.','Ensure good drainage, avoid overhead irrigation, practice crop rotation with non-allium species, and maintain proper plant spacing.','State Department of Agriculture','2026-08-04 12:41:05.233959'),(16,7,'/uploads/diseases/d0ffe3d4-9b92-48c7-846f-7aaadd5d404a.jpg','कापसावरील अल्टरनेरिया ठिपके (Alternaria Leaf Spot)',92,'पानांवर गोल किंवा वेडेवाकडे काळे-तपकिरी रंगाचे ठिपके पडतात, ज्यांच्या कडा गडद असतात. रोग वाढल्यास पानांना छिद्रे पडतात आणि पाने गळून पडतात.','१. ट्रायकोडेर्मा व्हिरिडे (Trichoderma viride) ५ ग्रॅम प्रति लिटर पाण्यात मिसळून फवारणी करावी. २. नीम तेल (५% अर्क) ची नियमित फवारणी करावी.','१. पिकांची योग्य फेरपालट करावी. २. शेतात अतिरिक्त पाणी साचू देऊ नये. ३. रोगाचा प्रादुर्भाव वाढल्यास मॅन्कोझेब (Mancozeb) किंवा कॉपर ऑक्सिक्लोराईड (Copper Oxychloride) २.५ ग्रॅम प्रति लिटर पाण्यात मिसळून फवारणी करावी.','State Department of Agriculture','2026-08-04 12:44:52.345372'),(17,7,'/uploads/diseases/3dae963a-5d96-40be-9e78-09663e6bbf98.jpg','Purple Blotch',94,'Elongated, oval, sunken lesions that turn purple-to-brown with reddish margins on leaf blades and stalks.','Apply bio-fungicides such as Trichoderma viride or spray neem oil (5 ml/L of water) evenly over foliage.','Ensure good crop rotation, avoid overhead irrigation to reduce leaf wetness, space plants properly, and apply Mancozeb or Copper Oxychloride fungicides as preventive sprays.','State Department of Agriculture','2026-08-04 17:15:57.133499'),(18,7,'/uploads/diseases/60f36219-60b5-47ce-b89e-3aee77fa778d.jpg','Alternaria Leaf Spot',92,'Circular to irregular brown spots with light tan centers and dark reddish-purple margins on leaves, causing tissue necrosis and leaf defoliation.','Apply neem oil (5 ml/L) or biological formulations containing Pseudomonas fluorescens or Trichoderma viride.','Ensure balanced nutrition, particularly potassium fertilization; avoid high canopy humidity; rotate with non-host crops and clean plant debris post-harvest.','State Department of Agriculture','2026-08-04 18:29:59.619799'),(19,7,'/uploads/diseases/e8a1d295-e398-487b-be04-bab0eba18ede.jpg','Healthy',96,'The corn cob and surrounding leaves appear healthy with no visible signs of disease, spots, discoloration, or pest damage.','No treatment required as the crop is healthy.','Maintain good crop management practices, balanced irrigation, and proper fertilization to sustain crop health.','State Department of Agriculture','2026-08-04 18:31:05.265783'),(20,7,'/uploads/diseases/e5a906f8-fc56-4fd7-83d9-8fefbd6e7340.jpg','अल्टरनेरिया पानावरील ठिपके (Alternaria Leaf Spot)',92,'पानांवर लहान ते मध्यम आकाराचे गोल किंवा अनियमित तपकिरी ठिपके दिसतात, ज्यांच्या कडा गडद जांभळ्या किंवा काळ्या रंगाच्या असतात. प्रादुर्भाव वाढल्यास पाने वाळतात आणि गळतात.','लिंबोळी अर्क (५%) किंवा नीम तेलाची (५ मिली/लिटर) फवारणी करा. प्रादुर्भाव झालेली पाने काढून नष्ट करा.','पिकांची फेरपालट करा, शेतात पाण्याचा निचरा योग्य ठेवा आणि झाडांमध्ये योग्य अंतर ठेवून हवा खेळती राहील याची काळजी घ्या.','State Department of Agriculture','2026-08-04 18:51:18.282877'),(21,16,'/uploads/diseases/f87e7e70-f35d-4aa0-8a08-ce0b61fd5d55.jpg','Healthy',96,'No visible symptoms of disease or nutrient deficiency. Leaves are green and intact, and the corn cobs are developing normally.','No organic treatment is required as the plant appears healthy.','Maintain proper irrigation schedules, weed management, and monitor regularly for early signs of pests or disease.','State Department of Agriculture','2026-08-05 18:04:33.602377'),(22,7,'/uploads/diseases/342a677a-49b1-4218-9239-fcc17714b795.jpg','Cotton Boll Rot',92.5,'Fungal infection during humid conditions.','Remove infected bolls, apply copper-based fungicide.','Ensure good air circulation, avoid overhead irrigation.','State Department of Agriculture','2026-08-05 21:12:04.287895'),(23,7,'maize images.jpg','Healthy Plant (Corn / Maize)',95,'Cause: None detected. The crop displays healthy green foliage and well-developed cobs with no visible symptoms of disease or nutrient deficiency.. Fertilizer: Apply balanced NPK fertilizers (e.g., 12-32-16 or balanced side-dressing with Urea/Nitrogen) according to crop stage to support grain filling.','No curative treatment is necessary. Continue standard management practices.','Maintain optimal irrigation, practice crop rotation, weed regularly, and continuously monitor for early signs of pests or disease.','State Department of Agriculture','2026-08-06 09:41:28.948398'),(24,7,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria macrospora or Alternaria alternata, frequently triggered by potassium deficiency and humid, wet weather conditions.. Fertilizer: Ensure adequate Potassium (K) nutrition using Muriate of Potash (MOP) or Potassium Nitrate spray, as potassium deficiency significantly increases susceptibility to this disease.','Apply foliar fungicides such as azoxystrobin, pyraclostrobin, difenoconazole, or copper oxychloride upon early detection of symptoms.','Use certified disease-free seeds, practice crop rotation with non-host crops, maintain proper plant spacing to improve canopy ventilation, and avoid overhead sprinkler irrigation.','State Department of Agriculture','2026-08-06 09:41:59.453009'),(25,7,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria macrospora or Alternaria alternata, favored by high humidity, warm temperatures, and plant stress or potassium deficiency.. Fertilizer: Apply balanced NPK fertilizer with adequate Potassium (Muriate of Potash), as potassium deficiency increases susceptibility to leaf spot diseases.','Apply foliar fungicides such as copper oxychloride, mancozeb, or azoxystrobin at the early onset of disease symptoms.','Use certified disease-free seeds, practice crop rotation with non-host crops, destroy infected crop residue after harvest, and avoid prolonged canopy wetness.','State Department of Agriculture','2026-08-06 10:08:05.684520'),(26,7,'maize images.jpg','Healthy Crop (Maize / Corn)',95,'Cause: None (The plant appears healthy with vibrant green foliage and well-developed cobs). Fertilizer: Apply balanced N-P-K fertilizers appropriate for corn development, along with periodic nitrogen side-dressing during early vegetative growth.','No curative treatment required as the plant shows no signs of disease or pest infestation.','Maintain optimal irrigation, practice field sanitation and crop rotation, and conduct regular scouting for potential pests like corn borers or armyworms.','State Department of Agriculture','2026-08-06 10:10:13.798336'),(27,7,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria macrospora or Alternaria alternata, favored by high humidity, frequent rain, leaf wetness, and potassium deficiency in the soil.. Fertilizer: Ensure adequate Potassium (K) fertilization, as potassium deficiency exacerbates leaf spot susceptibility. Apply a balanced NPK fertilizer.','Foliar application of fungicides such as copper oxychloride, azoxystrobin, or difenoconazole according to local agricultural recommendations.','Practice crop rotation with non-host crops, destroy infected crop residues after harvest, use certified disease-free seeds, and maintain optimal plant spacing to promote air circulation.','State Department of Agriculture','2026-08-06 11:17:07.950742'),(28,7,'GRAPES images.jpg','Healthy',95,'Cause: None. Fertilizer: Apply balanced NPK fertilizers during early spring growth, followed by potassium-rich fertilizers during berry development to enhance fruit quality.','None','Maintain proper canopy management through regular pruning to improve air circulation and sunlight penetration. Ensure adequate soil drainage and regular monitoring for pests or early fungal symptoms.','State Department of Agriculture','2026-08-06 18:36:50.825152'),(29,7,'images.jpg','Botrytis Bunch Rot (Grey Mold)',95,'Cause: Fungal infection caused by Botrytis cinerea, favored by high humidity, rainfall, and poor canopy air circulation during grape ripening.. Fertilizer: Avoid over-application of nitrogen fertilizers, which promotes dense canopy growth and increases susceptibility to soft tissue infections.','Apply appropriate bio-fungicides (e.g., Bacillus subtilis) or chemical fungicides containing cyprodinil, fludioxonil, or fenhexamid during susceptible growth stages (bloom, pre-bunch closure, veraison).','Practice fruit-zone leaf removal (plucking leaves around grape bunches) to enhance air circulation and sunlight exposure. Maintain proper shoot positioning and manage canopy density.','State Department of Agriculture','2026-08-07 17:47:27.953794'),(30,7,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria species (e.g., Alternaria macrospora or Alternaria alternata), favored by warm, humid conditions and plant stress like potassium deficiency.. Fertilizer: Apply balanced fertilizers with adequate Potassium (e.g., Potassium Sulfate or Muriate of Potash), as potassium-deficient cotton plants are highly susceptible.','Apply recommended foliar fungicides containing copper oxychloride, mancozeb, azoxystrobin, or difenoconazole at early disease onset.','Use resistant or tolerant cultivars, practice crop rotation with non-host crops, manage crop canopy to improve air circulation, and destroy post-harvest crop residue.','State Department of Agriculture','2026-08-07 17:58:05.743389'),(31,7,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungal infection caused by Alternaria macrospora or Alternaria alternata, often favored by high humidity, warm temperature, and potassium deficiency in the plant.. Fertilizer: Ensure adequate potassium (K) nutrition by applying Muriate of Potash (MOP) or Potassium Sulfate, as potassium deficiency significantly increases susceptibility to leaf spot diseases.','Apply foliar fungicides such as azoxystrobin, difenoconazole, mancozeb, or copper oxychloride as soon as early symptoms appear.','Plant disease-resistant cotton cultivars, maintain balanced soil fertility, practice crop rotation with non-host crops, and clear or plow under crop residues after harvest to reduce pathogen carryover.','State Department of Agriculture','2026-08-07 18:14:41.405871'),(32,7,'Diagnosis-Management-Foliar-Diseases-2.jpg','Alternaria Leaf Spot',95,'Cause: Fungus (Alternaria macrospora or Alternaria alternata). Fertilizer: Ensure adequate potassium supply; potassium deficiency increases susceptibility to Alternaria leaf spot.','Apply foliar fungicides such as mancozeb, copper oxychloride, or azoxystrobin upon early detection of symptoms.','Use resistant or tolerant cotton varieties, practice 2-3 year crop rotation with non-host crops, destroy crop residue post-harvest, and avoid overhead irrigation to minimize canopy wetness.','State Department of Agriculture','2026-08-07 18:19:04.889774');
