INSERT INTO `governmentschemes` VALUES (1,'PM-Kisan Samman Nidhi','Income support scheme providing ₹6,000 per year in three equal installments directly to bank accounts of landholder farmer families.','₹6,000 per year in three equal installments','All landholder farmer families across the country','https://pmkisan.gov.in/','Active'),(2,'Pradhan Mantri Fasal Bima Yojana (PMFBY)','Crop insurance scheme safeguarding farmers against crop failures due to natural disasters, pests, or diseases.','Comprehensive low-premium risk coverage (1.5% - 2% premium for foodgrains, 5% for commercial/horticultural)','All farmers growing notified crops in notified areas','https://pmfby.gov.in/','Active'),(3,'Kisan Credit Card (KCC)','Provides farmers with simple and low-interest credit for purchase of agricultural inputs, crop production, and asset maintenance.','Interest rates as low as 4% on timely repayment, short term credit up to ₹3 Lakhs','All farmers, owner-cultivators, tenant farmers, and sharecroppers','https://www.sbi.co.in/web/personal-banking/loans/agriculture-rural/kisan-credit-card','Active'),(4,'Soil Health Card Scheme','Evaluates soil nutrient status on 12 key parameters (NPK, pH, salinity, etc.) and provides customized crop and fertilizer advisor sheets.','Personalized soil test cards distributed every 2 years with advisory reports','All farmers holding cultivable land in India','https://soilhealth.dac.gov.in/','Active'),(5,'Per Drop More Crop (Micro Irrigation)','Promotes micro-irrigation systems like drip and sprinkler systems to improve water use efficiency.','Up to 55% subsidy for small and marginal farmers, and 45% for other categories','All farmers owning land and utilizing micro irrigation techniques','https://pmksy.gov.in/','Active'),(6,'Fertilizer Subsidy Scheme','Ensures urea, DAP, and complex NPK fertilizers are made available to farmers at controlled, subsidized prices.','Highly subsidized prices at retail points using POS direct verification','All farmers purchasing fertilizers for agricultural use','https://urvarak.nic.in/','Active');
/*!40000 ALTER TABLE `governmentschemes` ENABLE KEYS */;
UNLOCK TABLES;

